UPDATE torn_stock_notice_audit SET payload_snapshot = source.payload_snapshot, payload_hash = source.payload_hash, attempted_at = source.attempted_at, update_time = CURRENT_TIMESTAMP FROM (VALUES
(CAST(#{cmd.noticeId} AS BIGINT), CAST(#{cmd.payloadSnapshot} AS jsonb), #{cmd.payloadHash}, CAST(#{cmd.attemptedAt} AS TIMESTAMP))
) AS source(notice_id, payload_snapshot, payload_hash, attempted_at) WHERE torn_stock_notice_audit.id = source.notice_id AND torn_stock_notice_audit.deleted = 0 AND torn_stock_notice_audit.send_status = 'PENDING'
